const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Etosha Pan geometry and time periods
  const etosha = ee.Geometry.Point([15.8, -19.0]).buffer(25000); // 25km radius

  const date1Start = '2020-01-10';
  const date1End = '2020-01-20';
  const date2Start = '2020-08-20';
  const date2End = '2020-08-30';

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Water detection function using MNDWI
  function addWater(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('water');
    const waterMask = mndwi.gt(0.1); // Threshold for water
    return image.addBands(waterMask);
  }

  // 4. Get Sentinel-2 data for period 1 (mid-January)
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(etosha)
    .filterDate(date1Start, date1End)
    .map(maskS2clouds);

  const size1 = col1.size().getInfo();
  console.log(`Period 1 (Jan 2020): ${size1} images`);

  if (size1 === 0) {
    console.log('No images for January 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get Sentinel-2 data for period 2 (late August)
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(etosha)
    .filterDate(date2Start, date2End)
    .map(maskS2clouds);

  const size2 = col2.size().getInfo();
  console.log(`Period 2 (Aug 2020): ${size2} images`);

  if (size2 === 0) {
    console.log('No images for August 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate water extent for both periods
  const img1 = col1.median().clip(etosha);
  const img2 = col2.median().clip(etosha);

  const water1 = addWater(img1).select('water');
  const water2 = addWater(img2).select('water');

  // 7. Count valid pixels
  const count1 = water1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: etosha,
    scale: 3000,
    maxPixels: 1e9
  }).get('water').getInfo();

  const count2 = water2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: etosha,
    scale: 3000,
    maxPixels: 1e9
  }).get('water').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels - Jan: ${count1}, Aug: ${count2}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate water area (sum of water pixels)
  const waterArea1 = water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: etosha,
    scale: 3000,
    maxPixels: 1e9
  }).get('water').getInfo();

  const waterArea2 = water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: etosha,
    scale: 3000,
    maxPixels: 1e9
  }).get('water').getInfo();

  // 9. Validation
  if (waterArea1 === null || waterArea2 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Jan 2020 water pixels: ${Math.round(waterArea1)} (${count1} valid)`);
  console.log(`Aug 2020 water pixels: ${Math.round(waterArea2)} (${count2} valid)`);
  console.log(`Change: ${Math.round(waterArea2 - waterArea1)} pixels`);

  // 10. Final answer
  if (waterArea2 < waterArea1) {
    console.log('Water extent decreased from January to August 2020');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water extent did not decrease');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
